-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"الاستماع وتدوين الفكرة الأساسية","passage":"قرأ المعلّم خبرًا قصيرًا: زار طلاب الصف مكتبة المدرسة، واختار كل فريق كتابًا مناسبًا، ثم كتب الطلاب ملخصًا من جملتين وقدّموه لزملائهم. يميز المستمع بين الحدث الرئيس والتفاصيل المساندة ولا يخلط الاختيار بالتلخيص.","prompt":"ما الذي فعله الطلاب بعد اختيار الكتب؟","correct":"كتبوا ملخصًا من جملتين","w1":"أغلقوا المكتبة","w2":"أعادوا الكتب دون قراءة","w3":"سافروا خارج البحرين","practice":"استمع إلى نص جديد يقرأه المعلم مرتين، ثم دوّن الفكرة الرئيسة وتفصيلين يدعمانها دون نسخ كل كلمة."},{"n":2,"skill":"فهم رغبة الطفل واحترام الحوار","passage":"قالت ليلى لأمها في نص تدريبي من إنشاء ضاديوم: أحب قضاء الوقت معك، ولكني أحتاج وقتًا لألعب بعد إنهاء واجباتي. أجابت الأم: نتفق على وقت للدراسة وآخر للعب. يدل الحوار على إمكان التعبير عن الرغبة باحترام، ولا يمثل أحداث نص القراءة الأصلي.","prompt":"ما الحل الذي اقترحته الأم في النص التدريبي؟","correct":"تنظيم وقت للدراسة وآخر للعب","w1":"منع اللعب نهائيًا","w2":"ترك الواجبات كلها","w3":"عدم الاستماع إلى ليلى","practice":"اكتب حوارًا من ستة أسطر بين طفل ووالده يوضح رغبة الطفل وسببها وكيف يصل الطرفان إلى اتفاق."},{"n":3,"skill":"الحال ودلالته وإعرابه","passage":"في الجملة: عادَ الطالبُ مسرورًا؛ كلمة «مسرورًا» حالٌ منصوبة تصف هيئة الطالب وقت العودة، وصاحب الحال «الطالب». نقارنها بقولنا «عاد الطالبُ»: الفعل والفاعل واضحان، لكن وصف الهيئة اختفى. الحال في هذا المثال اسم نكرة منصوب.","prompt":"ما إعراب «مسرورًا» في «عاد الطالب مسرورًا»؟","correct":"حال منصوبة","w1":"مبتدأ مرفوع","w2":"مفعول به منصوب","w3":"خبر كان منصوب","practice":"اكتب ثلاث جمل فيها أحوال مختلفة، وضع خطًا تحت الحال وحدد صاحبها وعلامة نصبها."},{"n":4,"skill":"استخلاص الفكرة والدليل من قصة قصيرة","passage":"رسم خالد نموذجًا لطائرة صغيرة وحاول تشغيله فلم ينجح. طلب مشورة معلم العلوم، وعدّل المروحة، ثم طارت الطائرة لمسافة قصيرة. في هذا الموقف الإثرائي يتحول الحلم إلى خطوات وتجربة وتصحيح للخطأ؛ وهو ليس تلخيصًا لنص «حلم طفل» في الكتاب.","prompt":"ما الذي ساعد خالد على تقدم تجربته؟","correct":"طلب المشورة وتعديل المروحة","w1":"إلغاء التجربة","w2":"إخفاء النموذج","w3":"رفض أي مساعدة","practice":"اكتب فقرة من خمسة أسطر عن حلم واقعي يتطلب تخطيطًا، واذكر عقبة وحلًا ودليلًا من تجربتك أو خيالك."},{"n":5,"skill":"بناء رسالة شخصية واضحة","passage":"تبدأ الرسالة الشخصية بتحية مناسبة، تليها جمل توضح سبب الكتابة، ثم خاتمة ودودة واسم المرسل. مثال أصلي: «صديقي العزيز، قرأت رسالتك عن مسابقة الرسم وسررت بمشاركتك. أتمنى لك النجاح. صديقك سالم». ترتيب العناصر يجعل الرسالة مفهومة ومناسبة للمتلقي.","prompt":"ما العنصر الذي يوضح سبب كتابة الرسالة؟","correct":"متن الرسالة","w1":"اسم المرسل وحده","w2":"تاريخ خارج الرسالة فقط","w3":"شكل الظرف وحده","practice":"اكتب رسالة إلى صديق تدعوه للمشاركة في نشاط مدرسي مع تحية وسبب الدعوة وخاتمة وتوقيع."},{"n":6,"skill":"استنتاج المشاعر من رسائل قصيرة","passage":"في ثلاث رسائل تدريبية أصلية كتب طفل إلى معلمته: شكرًا لتشجيعك؛ ثم كتب لصديقه: افتقدت حديثنا؛ ثم كتب لأسرته: تعلمت أن المحاولة أهم من الخوف. نحدد مخاطَب كل رسالة والشعور الذي يثبته اللفظ. هذه رسائل من إنشاء ضاديوم، وليست اقتباسًا من «ثلاث رسائل من تيدي».","prompt":"أي عبارة في الرسائل التدريبية تدل مباشرة على الامتنان؟","correct":"شكرًا لتشجيعك","w1":"افتقدت حديثنا","w2":"المحاولة أهم من الخوف","w3":"ثلاث رسائل","practice":"اكتب رسالتين قصيرتين لمتلقيين مختلفين، ثم اشرح كيف غيّرت الألفاظ لتناسب العلاقة والمشاعر."},{"n":7,"skill":"الاستثناء بإلا في الجملة التامة المثبتة","passage":"في جملة «حضر الطلابُ إلا طالبًا» ذُكر المستثنى منه «الطلاب»، والجملة مثبتة، لذا يُنصب المستثنى «طالبًا» بعد «إلا». هذا حكم الجملة التامة المثبتة تحديدًا؛ أما المنفية والناقصة فلها أحكام تحتاج أمثلة أخرى.","prompt":"ما إعراب «طالبًا» في «حضر الطلاب إلا طالبًا»؟","correct":"مستثنى منصوب","w1":"فاعل مرفوع","w2":"مضاف إليه مجرور","w3":"مبتدأ مرفوع","practice":"كوّن جملتين تامتين مثبتتين فيهما استثناء بإلا، ثم حدّد المستثنى منه والمستثنى وأعربه."},{"n":8,"skill":"تحديد المشاعر في مقطع وصفي","passage":"في مقطع وصفي مستقل: امتلأت الساحة بأصوات الصغار، وتبادل الأصدقاء الألعاب، وضحك طفل حين استطاع القفز فوق خط رسمه بالطباشير. تعطي الأفعال والأصوات قرائن على البهجة، لكن فهم قصيدة «لله ما أحلى الطفولة» نفسها يتطلب الرجوع إلى النص الأدبي.","prompt":"ما الشعور الذي يبرزه المقطع التدريبي؟","correct":"الفرح والبهجة","w1":"الخوف الشديد","w2":"الحزن الدائم","w3":"اللامبالاة","practice":"اكتب أربعة أسطر تصف موقفًا سعيدًا في الطفولة مستخدمًا صورتين حسيتين، ثم حدد الألفاظ الدالة على الشعور."},{"n":9,"skill":"كتابة المقال: الفكرة والحجة والتنظيم","passage":"المقال الجيد يعرض فكرة محددة في المقدمة، ثم يقدم حجة وأمثلة في العرض، ويختم بنتيجة متصلة بالفكرة. مثال موضوع «القراءة اليومية»: الدعوى أن عشر دقائق منتظمة تنمّي المفردات؛ والدليل ملاحظة الكلمات الجديدة وتوظيفها في الكتابة. يجب التفريق بين الرأي والدليل وعدم عرض الانطباع وكأنه حقيقة مقيسة.","prompt":"أين تُعرض الأدلة والأمثلة الرئيسة عادة في المقال؟","correct":"في العرض","w1":"في العنوان وحده","w2":"بعد التوقيع","w3":"في الهامش فقط","practice":"اكتب مقالًا قصيرًا عن عادة مفيدة بثلاث فقرات: مقدمة وفكرتين مدعومتين بمثال وخاتمة."},{"n":10,"skill":"قراءة الأثر الأدبي بالدليل دون اختلاق أحداث","passage":"لفهم فصول رواية «الأيام» من 7 إلى 13 ينبغي قراءة النص الأصلي أولًا وتحديد الراوي والمكان والزمان والتحول في الشخصية مع شاهد نصي. تدريب مستقل: «توقف الفتى عند الباب لحظة، ثم عاد خطوة، قبل أن يتشجع ويدخل». نستدل على تردده من وقوفه ورجوعه، من غير نسبة هذا الموقف إلى الرواية.","prompt":"ما الدليل المباشر على تردد الفتى في المقطع المستقل؟","correct":"وقف لحظة ثم عاد خطوة","w1":"دخل مباشرة دون تردد","w2":"أنهى الكتاب","w3":"سافر إلى مكان آخر","practice":"بعد قراءة الفصول المحددة من المصدر المصرح به، سجّل حدثين حقيقيين بشواهد من النص، وميزها عن التفسير الشخصي."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=8
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عدسات صغيرة' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF coalesce(trim(target_content),'')='' THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.',
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_G8_T1_SMALL_LENSES_ORIGINAL_10_20261008','notOfficialBook',true,'ocrReview','pending','options',jsonb_build_array(r.correct,r.w1,r.w2,r.w3)),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_G8_T1_SMALL_LENSES_ORIGINAL_10_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_G8_T1_SMALL_LENSES_ORIGINAL_10_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_G8_T1_SMALL_LENSES_ORIGINAL_10_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;